def even_odd_count(num):
    num = abs(num)  # Work with the absolute value to ignore the sign
    evens = 0
    odds = 0

    for digit in str(num):  # Convert the number to string to iterate over each digit
        if int(digit) % 2 == 0:
            evens += 1
        else:
            odds += 1

    return (evens, odds)

